#!/usr/bin/env bash
# Section-specific assets for the live build (sections 2, 3 "Activity and rest", 4 "Made to be forgotten").
G="$(cd "$(dirname "$0")" && pwd)/genref.sh"
cd "$(dirname "$0")/../../../.."
RM=design/ring-master; M=design/assets/v1/masters; H=design/assets/v1/home
SET=$M/E-03-moss-rock-set.png; R4=$RM/04-three-quarter-outer.png; R8=$RM/08-flat-45.png; R2=$RM/02-side-profile.png
run(){ [[ -f "$2" ]] && { echo "SKIP $2"; return; }; "$G" "$@" || echo "FAIL $2"; }
BASE="Real product still-life photograph on a hand-built natural studio set, not a 3D render. Same set as the attached set reference: pale granite rock with warm rust-tinted mineral patches, a dense bed of real green cushion moss, soft out-of-focus fern fronds at a foreground edge, and a warm cream plaster wall behind with soft leaf shadows from sunlight through plants. Medium-format camera, 100 mm macro lens, true-to-life color, warm natural grade, soft film-like tonality, fine grain, real organic imperfections."
RING="The smart ring must match the attached ring reference exactly: smooth domed polished silver band about 7 mm wide, thin bright chamfered edges, black matte inner shell with two small square sensor windows and two small grey oval contact pads, sensors not lit. Realistic small scale (about 2 cm across) relative to the stones and moss. The ring rests physically with a clear contact shadow, never floating. Its surface reflects only the wall, moss and warm light, never a landscape or trees."
AVOID="Avoid: CGI or plastic look, HDR, neon or oversaturated green, floating ring, stacked stones, mossy log pedestal, gradient backdrop, flowers, water droplets, marble, lens flare, bokeh particles, vignette, text, numbers, logos, people, hands, extra jewelry."
P="--size 1080x1536"   # activity slides ~5:7 portrait
# ---- Section 2
run "$BASE 'Last night': the very first light of morning, about 06:30. The scene is still mostly in cool blue-grey night tones; only the upper part of the wall is touched by a thin band of first warm sunlight. The silver ring lies on its side, resting quietly on the soft moss at the foot of the rock, as if it has been there all night. Calm, hushed, still. Vertical 4:5, camera low at moss level, ring in the lower third, quiet wall space above. $RING $AVOID" $H/S2-01-last-night.png --size 1232x1536 --ref $SET --ref $R8 &
run "$BASE 'Patterns, not scores': seven small smooth pale river pebbles laid in a loose, gently curving single row across the moss in front of the granite rock, like the days of a week. Their sizes vary irregularly and are NOT sorted: small, large, medium, small, large, medium, small, so the row reads as a natural uneven rhythm, never as growth, progress or a ranking. None are marked. The silver ring lies on its side at the end of the row, about the size of the pebbles. Warm clear morning light about 4800K from the left, soft leaf shadows on the wall. Vertical 4:5, camera at about 35 degrees above, the row leading the eye from lower left to the ring at right. $RING $AVOID Also avoid: pebbles stacked, pebbles sorted from small to large, numbers or marks on pebbles." $H/S2-02-patterns.png --size 1232x1536 --ref $SET --ref $R8 &
wait
# ---- Section 3: Activity and rest (Moving = ring upright; Resting = ring lying flat)
run "$BASE 07:40, Moving, a morning walk. Two flat pale stepping stones set into the moss form a short path leading back toward the rock. The silver ring stands upright on its edge on the nearer stepping stone, as if mid-roll along the path. Low warm early sun from the left, about 3600K, long soft shadows pointing right, long leaf shadows on the wall. Vertical 5:7, camera low, path receding into the frame. $RING $AVOID" $H/S3-0740-moving-walk.png $P --ref $SET --ref $R4 &
run "$BASE 09:00, Resting, a long quiet focus. The silver ring lies flat and perfectly still on the smooth top of the granite rock. Clear, calm, even morning light about 5000K, crisp but gentle leaf shadows on the wall, nothing moving. Vertical 5:7, camera slightly above, ring centered on the rock with calm space around it. $RING $AVOID" $H/S3-0900-resting-focus.png $P --ref $SET --ref $R8 &
run "$BASE 10:30, Moving, a stretch. A long fern frond reaches and stretches diagonally across the scene from the moss up toward the wall. The silver ring stands upright on its edge on the rock, leaning slightly forward along the line of the frond. Bright fresh mid-morning sun about 5200K from the upper left, crisp elongated leaf shadows stretching across the wall. Vertical 5:7. $RING $AVOID" $H/S3-1030-moving-stretch.png $P --ref $SET --ref $R4 &
run "$BASE 12:30, Resting, a lunch pause. High overhead midday sun about 5600K filtered through leaves directly above: the whole rock, the ring and the moss are covered in strong, clearly visible dappled light, many small bright sun spots and dark leaf-shadow patches scattered over everything, like sitting under a tree at lunch. The wall is mostly in leaf shade. The silver ring lies flat on the rock, half in a dark leaf shadow and half touched by a small sun spot, resting. Vertical 5:7, camera looking down at about 70 degrees, so the scene looks clearly different from a frontal morning view. $RING $AVOID" $H/S3-1230-resting-lunch.png $P --ref $SET --ref $R8 &
wait
run "$BASE 15:30, Moving, stairs and errands. The granite rock is replaced by two or three natural pale stone ledges forming low irregular steps rising through the moss. The silver ring stands upright on its edge on the middle step, as if climbing. Warm afternoon sun from the right, about 4200K, shadows falling left, leaf shadows warm on the wall. Vertical 5:7, camera low looking slightly up the steps. $RING $AVOID" $H/S3-1530-moving-stairs.png $P --ref $SET --ref $R4 &
# ---- Section 4: Made to be forgotten (evening, 18:30)
run "$BASE 'One quiet band', evening about 18:30, warm low golden side light about 3600K. A soft undyed natural linen cord is loosely draped over the granite rock and across the silver ring, which lies on its side; the cord slides smoothly over the plain polished outer band with nothing to catch on, emphasizing the smooth uninterrupted outer surface. Landscape 11:8, camera at about 40 degrees, ring left of center. $RING $AVOID" $H/S4-01-quiet-band.png --size 1536x1120 --ref $SET --ref $R4 &
run "$BASE 'Softened edges', evening about 18:30. Macro side-profile view of the silver ring standing upright on the rock, seen almost edge-on so the low even profile of the band and the two bevelled, softened edges are clear. A single low warm raking light about 3400K traces a fine bright line along each bevel; the moss and wall fall into soft dusky warm blur. Landscape 11:8, ring center-left, 100 mm macro at close focus. $RING $AVOID" $H/S4-02-softened-edges.png --size 1536x1120 --ref $SET --ref $R2 &
run "$BASE 'Sensors on the inside', evening about 18:30. The silver ring lies tilted on its side on the moss against the rock so the camera looks into the smooth black matte inner surface: the two small square sensor windows and two small grey oval contact pads sit perfectly flush, dark, NOT lit, while the plain polished outer band shows nothing. Warm low light about 3600K grazes the inside. Landscape 11:8, ring slightly right of center. $RING $AVOID Also avoid: glowing LEDs, green or red lights." $H/S4-03-sensors-inside.png --size 1536x1120 --ref $SET --ref $RM/07-macro-sensors.png &
wait
echo SECTIONS V2 DONE
